<?php
require_once __DIR__ . '/../includes/config.php';
requireRole('lecturer');
$roleCheck=safeRun($pdo,'SELECT COUNT(*) c FROM lecturer_roles WHERE lecturer_id=? AND semester_id=?',[(int)$_SESSION['lecturer_id'],currentSemesterId($pdo)]);
if($roleCheck&&(int)$roleCheck->fetch()['c']>0)redirect(BASE_URL.'/dashboard/lecturer/index.php');
$systemName=getSetting($pdo,'system_name',APP_NAME)?:APP_NAME;
$institutionName=getSetting($pdo,'institution_name',APP_INSTITUTION)?:APP_INSTITUTION;
$darkMode=getSetting($pdo,'dark_mode','0')==='1';
?>
